// MailoHLS external/unseen application input.
// Adapted from the HLSyn/HierarchicalMoE trmm-opt kernel.
// Optimization pragmas from the upstream DSE template were removed; MailoHLS Lk action anchors were added.

extern "C" {
void kernel_trmm(double alpha, double A[60][60], double B[60][80])
{
  // BLAS parameters: SIDE='L', UPLO='L', TRANSA='T', DIAG='U'.
  // B := alpha * A^T * B.

/*L1:*/  for (int i = 0; i < 60; i++) {
#pragma HLS pipeline II=auto{_PIPE_L1}
#pragma HLS unroll factor=auto{_UNROLL_L1}
/*L2:*/    for (int j = 0; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
      double sum = B[i][j];
/*L3:*/      for (int k = 0; k < 60; k++) {
#pragma HLS pipeline II=auto{_PIPE_L3}
#pragma HLS unroll factor=auto{_UNROLL_L3}
        if (k > i) {
          sum += A[k][i] * B[k][j];
        }
      }
      B[i][j] = alpha * sum;
    }
  }
}
}

// MailoHLS external/unseen application input.
// Adapted from the HLSyn/HierarchicalMoE jacobi-2d kernel.
// Optimization pragmas from the upstream DSE template were removed; MailoHLS Lk action anchors were added.

extern "C" {
void kernel_jacobi_2d(int tsteps, int n, double A[90][90], double B[90][90])
{
  int t;
  int i;
  int j;

/*L1:*/  for (t = 0; t < 40; t++) {
#pragma HLS pipeline II=auto{_PIPE_L1}
#pragma HLS unroll factor=auto{_UNROLL_L1}
/*L2:*/    for (i = 1; i < 89; i++) {
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
/*L3:*/      for (j = 1; j < 89; j++) {
#pragma HLS pipeline II=auto{_PIPE_L3}
#pragma HLS unroll factor=auto{_UNROLL_L3}
        B[i][j] = 0.2 * (A[i][j] + A[i][j - 1] + A[i][1 + j]
                         + A[1 + i][j] + A[i - 1][j]);
      }
    }

/*L4:*/    for (i = 1; i < 89; i++) {
#pragma HLS pipeline II=auto{_PIPE_L4}
#pragma HLS unroll factor=auto{_UNROLL_L4}
/*L5:*/      for (j = 1; j < 89; j++) {
#pragma HLS pipeline II=auto{_PIPE_L5}
#pragma HLS unroll factor=auto{_UNROLL_L5}
        A[i][j] = 0.2 * (B[i][j] + B[i][j - 1] + B[i][1 + j]
                         + B[1 + i][j] + B[i - 1][j]);
      }
    }
  }
}
}

// MailoHLS external/unseen application input.
// Adapted from the HLSyn/HierarchicalMoE covariance kernel.
// Optimization pragmas from the upstream DSE template were removed; MailoHLS Lk action anchors were added.

extern "C" {
void kernel_covariance(int m, int n, double float_n,
                       double data[100][80],
                       double cov[80][80],
                       double mean[80])
{
  int i;
  int j;
  int k;

/*L1:*/  for (j = 0; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L1}
#pragma HLS unroll factor=auto{_UNROLL_L1}
    mean[j] = 0.0;
/*L2:*/    for (i = 0; i < 100; i++) {
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
      mean[j] += data[i][j];
    }
    mean[j] /= float_n;
  }

/*L3:*/  for (i = 0; i < 100; i++) {
#pragma HLS pipeline II=auto{_PIPE_L3}
#pragma HLS unroll factor=auto{_UNROLL_L3}
/*L4:*/    for (j = 0; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L4}
#pragma HLS unroll factor=auto{_UNROLL_L4}
      data[i][j] -= mean[j];
    }
  }

/*L5:*/  for (i = 0; i < 80; i++) {
#pragma HLS pipeline II=auto{_PIPE_L5}
#pragma HLS unroll factor=auto{_UNROLL_L5}
/*L6:*/    for (j = i; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L6}
#pragma HLS unroll factor=auto{_UNROLL_L6}
      cov[i][j] = 0.0;
/*L7:*/      for (k = 0; k < 100; k++) {
#pragma HLS pipeline II=auto{_PIPE_L7}
#pragma HLS unroll factor=auto{_UNROLL_L7}
        cov[i][j] += data[k][i] * data[k][j];
      }
      cov[i][j] /= float_n - 1.0;
      cov[j][i] = cov[i][j];
    }
  }
}
}

// MailoHLS external/unseen application input.
// Adapted from the HLSyn/HierarchicalMoE syr2k kernel.
// Optimization pragmas from the upstream DSE template were removed; MailoHLS Lk action anchors were added.

extern "C" {
void kernel_syr2k(double alpha, double beta,
                  double C[80][80], double A[80][60], double B[80][60])
{
  int i;
  int j;
  int k;
  // BLAS parameters: UPLO='L', TRANS='N'; A/B are NxM and C is NxN.

/*L1:*/  for (i = 0; i < 80; i++) {
#pragma HLS pipeline II=auto{_PIPE_L1}
#pragma HLS unroll factor=auto{_UNROLL_L1}
/*L2:*/    for (j = 0; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
      if (j <= i) {
        C[i][j] *= beta;
      }
    }

/*L3:*/    for (k = 0; k < 60; k++) {
#pragma HLS pipeline II=auto{_PIPE_L3}
#pragma HLS unroll factor=auto{_UNROLL_L3}
/*L4:*/      for (j = 0; j < 80; j++) {
#pragma HLS pipeline II=auto{_PIPE_L4}
#pragma HLS unroll factor=auto{_UNROLL_L4}
        if (j <= i) {
          C[i][j] += A[j][k] * alpha * B[i][k]
                   + B[j][k] * alpha * A[i][k];
        }
      }
    }
  }
}
}
